import users from './users.json' with { type: 'json' };

const TOOLS = [
  {
    name: 'users_get_many',
    description:
      'Look up multiple users by id in a single batch. Missing ids are ' +
      'reported without failing the whole batch.',
    inputSchema: {
      type: 'object',
      properties: {
        user_ids: {
          type: 'array',
          items: { type: 'string' },
          minItems: 1,
          maxItems: 5,
          uniqueItems: true,
          description:
            'Unique user ids to look up. Order is preserved in the response.',
        },
      },
      required: ['user_ids'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected a JSON object');
  }

  // Reject any field that is not declared in the input schema.
  const allowed = new Set(['user_ids']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  if (!Object.prototype.hasOwnProperty.call(args, 'user_ids')) {
    throw new Error('Missing required argument: user_ids');
  }

  const ids = args.user_ids;
  if (!Array.isArray(ids)) {
    throw new Error('user_ids must be an array');
  }
  if (ids.length === 0) {
    throw new Error('user_ids must not be empty');
  }
  if (ids.length > 5) {
    throw new Error('user_ids must contain at most 5 entries');
  }

  const seen = new Set();
  for (const id of ids) {
    if (typeof id !== 'string') {
      throw new Error('user_ids entries must be strings');
    }
    if (seen.has(id)) {
      throw new Error(`Duplicate user_id: ${id}`);
    }
    seen.add(id);
  }

  const lines = ids.map((id) => {
    const user = users[id];
    return user ? `${id}: ${user.name}` : `${id}: missing`;
  });

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

